param([ValidateSet('RED','GREEN')][string]$Phase='GREEN',[string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent (Split-Path -Parent $PSScriptRoot))))
$ErrorActionPreference='Stop'; Import-Module (Join-Path $RepositoryRoot 'evals\lib\TestHarness.psm1') -Force
function Invoke-Sc31 {
    Import-Module (Join-Path $RepositoryRoot 'scripts\lib\ProjectFlightControl.Doctor.psm1') -Force
    $root=Join-Path ([IO.Path]::GetTempPath()) ('pfc-sc31-'+[guid]::NewGuid().ToString('N'));$fixtureHome=Join-Path $root 'home';$state=Join-Path $root 'state';New-Item -ItemType Directory -Path $fixtureHome,$state|Out-Null;$results=New-Object System.Collections.Generic.List[object]
    function Check([string]$id,[bool]$ok,[string]$message){$results.Add((New-PfcResult $id $(if($ok){'PASS'}else{'FAIL'}) $message))}
    try {
        $agentDir=Join-Path $fixtureHome '.codex\agents';$skillDir=Join-Path $fixtureHome '.codex\skills\project-flight-control';New-Item -ItemType Directory -Path $agentDir,$skillDir -Force|Out-Null;Copy-Item (Join-Path $RepositoryRoot 'codex-agents\project-flight-builder.toml') (Join-Path $agentDir 'project-flight-builder.toml');Copy-Item (Join-Path $RepositoryRoot 'codex-agents\project-flight-verifier.toml') (Join-Path $agentDir 'project-flight-verifier.toml');Copy-Item (Join-Path $RepositoryRoot 'skill\project-flight-control\SKILL.md') (Join-Path $skillDir 'SKILL.md')
        $base=[pscustomobject]@{Product='Project Flight Control';Version='0.1.0-dev.0';ManagedFiles=@();SpecialistCapabilityRecord=$null}
        $unknown=Get-PfcSpecialistCapabilityState -Manifest $base -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome -StateRoot $state;Check 'sc31.no-record-unknown' ($unknown.status -eq 'UNKNOWN') ('status='+$unknown.status)
        $unavailable=Get-PfcSpecialistCapabilityState -Manifest ([pscustomobject]@{SpecialistCapabilityRecord=$null;SpecialistPrerequisite=$false}) -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome -StateRoot $state;Check 'sc31.explicit-prerequisite-unavailable' ($unavailable.status -eq 'UNAVAILABLE') ('status='+$unavailable.status)
        Set-Content -LiteralPath (Join-Path $fixtureHome '.codex\config.toml') -Value 'sandbox_mode = "read-only"'
        $fp=Get-PfcDoctorFingerprint -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome
        Check 'sc31.worktree-probe-pass' ($fp.components.git_worktree_probe -eq 'PASS') ('worktree_probe='+$fp.components.git_worktree_probe+';message='+$fp.components.git_worktree_probe_message)
        Check 'sc31.explicit-read-only-pass' ($fp.components.sandbox_permission -eq 'PASS' -and $fp.components.sandbox_permission_mode -eq 'read-only') ('permission='+$fp.components.sandbox_permission)
        Check 'sc31.skill-major-unknown-without-explicit-field' ($fp.components.skill_major -eq 'UNKNOWN') ('skill_major='+$fp.components.skill_major)
        $valid=[pscustomobject]@{status='AVAILABLE';fingerprint=$fp.fingerprint;expires_at=[DateTime]::UtcNow.AddHours(1).ToString('o');isolation='PASS';sha='VALID';report='PASS';cleanup='PASS'};$available=Get-PfcSpecialistCapabilityState -Manifest ([pscustomobject]@{SpecialistCapabilityRecord=$valid}) -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome -StateRoot $state;Check 'sc31.matching-record-available' ($available.status -eq 'AVAILABLE') ('status='+$available.status)
        $fields=@('isolation','sha','report','cleanup');foreach($field in $fields){$invalid=$valid.PSObject.Copy();$invalid.$field='FAIL';$s=Get-PfcSpecialistCapabilityState -Manifest ([pscustomobject]@{SpecialistCapabilityRecord=$invalid}) -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome -StateRoot $state;Check ('sc31.failed-'+$field+'-unknown') ($s.status -eq 'UNKNOWN') ('status='+$s.status)}
        $expired=$valid.PSObject.Copy();$expired.expires_at=[DateTime]::UtcNow.AddHours(-1).ToString('o');$s=Get-PfcSpecialistCapabilityState -Manifest ([pscustomobject]@{SpecialistCapabilityRecord=$expired}) -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome -StateRoot $state;Check 'sc31.expired-unknown' ($s.status -eq 'UNKNOWN') ('status='+$s.status)
        $corrupt=$valid.PSObject.Copy();$corrupt.expires_at='corrupt';$s=Get-PfcSpecialistCapabilityState -Manifest ([pscustomobject]@{SpecialistCapabilityRecord=$corrupt}) -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome -StateRoot $state;Check 'sc31.corrupt-record-unknown' ($s.status -eq 'UNKNOWN') ('status='+$s.status)
        foreach($missingField in @('status','fingerprint','expires_at','isolation','sha','report','cleanup')){$missing=$valid.PSObject.Copy();$missing.PSObject.Properties.Remove($missingField);$s=Get-PfcSpecialistCapabilityState -Manifest ([pscustomobject]@{SpecialistCapabilityRecord=$missing}) -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome -StateRoot $state;Check ('sc31.missing-'+$missingField+'-unknown') ($s.status -eq 'UNKNOWN') ('status='+$s.status)}
        Add-Content -LiteralPath (Join-Path $agentDir 'project-flight-verifier.toml') -Value 'changed=true';$s=Get-PfcSpecialistCapabilityState -Manifest ([pscustomobject]@{SpecialistCapabilityRecord=$valid}) -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome -StateRoot $state;Check 'sc31.verifier-hash-mutation-unknown' ($s.status -eq 'UNKNOWN') ('status='+$s.status)
        Set-Content -LiteralPath (Join-Path $fixtureHome '.codex\config.toml') -Value 'sandbox_mode="workspace-write"';$before=Get-PfcDoctorFingerprint -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome;Add-Content -LiteralPath (Join-Path $fixtureHome '.codex\config.toml') -Value 'approval_policy="never"';$after=Get-PfcDoctorFingerprint -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome;Check 'sc31.sandbox-config-mutation-fingerprint' ($before.fingerprint -ne $after.fingerprint) 'sandbox config changes fingerprint'
        Check 'sc31.writable-permission-unknown' ($before.components.sandbox_permission -eq 'UNKNOWN' -and $before.components.sandbox_permission_mode -eq 'workspace-write') ('permission='+$before.components.sandbox_permission)
        Check 'sc31.writable-worktree-unknown' ($before.components.git_worktree_probe -eq 'UNKNOWN') ('worktree_probe='+$before.components.git_worktree_probe)
        Set-Content -LiteralPath (Join-Path $fixtureHome '.codex\config.toml') -Value 'sandbox_mode = [';$malformed=Get-PfcDoctorFingerprint -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome;Check 'sc31.malformed-permission-unknown' ($malformed.components.sandbox_permission -eq 'UNKNOWN') ('permission='+$malformed.components.sandbox_permission);Remove-Item -LiteralPath (Join-Path $fixtureHome '.codex\config.toml');$missingPermission=Get-PfcDoctorFingerprint -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome;Check 'sc31.missing-permission-unknown' ($missingPermission.components.sandbox_permission -eq 'UNKNOWN') ('permission='+$missingPermission.components.sandbox_permission);$doctorMissing=Invoke-PfcPassiveDoctor -UserHome $fixtureHome -StateRoot $state -RepositoryRoot $RepositoryRoot -ProcessInvoker {param($a) [pscustomobject]@{ExitCode=1;StdOut='';StdErr='unavailable'}};$doctorPermission=@($doctorMissing.checks|Where-Object{$_.id -eq 'sandbox-permission'})[0];Check 'sc31.doctor-missing-permission-unknown' ($doctorPermission.status -eq 'UNKNOWN') ('status='+$doctorPermission.status)
        $override=Get-PfcDoctorFingerprint -RepositoryRoot $RepositoryRoot -UserHome $fixtureHome -CodexVersion 'client-override';Check 'sc31.client-version-override' ($override.components.codex_version -eq 'client-override') ('client='+$override.components.codex_version)
        $missingRepo=Join-Path $root 'missing-source';New-Item -ItemType Directory -Path $missingRepo -Force|Out-Null;$d=Invoke-PfcPassiveDoctor -UserHome $fixtureHome -StateRoot $state -RepositoryRoot $missingRepo -ProcessInvoker {param($a);[pscustomobject]@{ExitCode=1;StdOut='';StdErr='unavailable'}};$hash=@($d.checks|Where-Object{$_.id -like 'formal-agent-hash-*'}|ForEach-Object{$_.status});Check 'sc31.missing-source-hash-unknown' (($hash -contains 'UNKNOWN')) (($hash -join ','));$skill=@($d.checks|Where-Object{$_.id -eq 'skill-install'})[0];Check 'sc31.missing-skill-source-unknown' ($skill.status -eq 'UNKNOWN') ('status='+$skill.status)
    } catch { $results.Add((New-PfcResult 'sc31.failure' 'FAIL' $_.Exception.Message)) } finally { if(Test-Path $root){Remove-Item -LiteralPath $root -Recurse -Force} }
    return $results.ToArray()
}
Invoke-Sc31
